+  for (const key of [publicKey, privateKey]) {
+    assert.strictEqual(await new Promise((resolve, reject) => {
+      verify(digest, data, key, signature, (err, result) => {
+        if (err) reject(err);
+        else resolve(result);
+      });
+    }), true);
+  }
