+    {"type_freeze", type_freeze, METH_O},
+    {"type_clearcache", type_clearcache, METH_NOARGS},
+    {"type_getflags", type_getflags, METH_O},
+    {"type_issubtype", type_issubtype, METH_VARARGS},
+    {NULL},
+};
+
+int
