+function workloadErrors(iterations) {
+  let ops = 0;
+
+  for (let i = 0; i < iterations; i++) {
+    // Error creation with stack trace
+    const err1 = new Error(`Something went wrong: ${i}`);
+    void err1.stack; // Access stack (forces stack trace computation)
