+    { name: 'HMAC', hash: 'SHA-256' },
+    false,
+    ['sign', 'verify'],
+  );
+
+  for (let i = 0; i < iterations; i++) {
+    const data = DATA_SIZES[i % 3]; // Keep data smaller for WebCrypto
+    const iv = crypto.randomBytes(12);
