+    let statement;
+    const invoke = (params) => (method === 'iterate' ?
+      [...statement.iterate(params)] :
+      statement[method](params));
+    const reenter = mustCall(() => {
+      assert.throws(() => invoke({ $min: 2 }), reentryError);
+      return 1;
+    });
+    const params = { get $min() { return reenter(); } };
