+  let inner;
+  const reenter = mustCall(() => {
+    assert.throws(() => {
+      inner = statement.iterate({ $min: 1 });
+    }, reentryError);
+    return 1;
+  });
+  const params = { get $min() { return reenter(); } };
+
+  assert.deepStrictEqual(
+    [...statement.iterate(params)].map((row) => row.value),
+    [1, 2, 3],
+  );
+  assert.strictEqual(inner, undefined);
+});

