+
+// Unpaired surrogates must not be returned as-is from href.
+{
+  const input = 'https://example.com/\uD800';
+  const url = new URL(input);
+  assert.notStrictEqual(url.href, input);
+  assert.ok(url.href.startsWith('https://example.com/'));
