+      assert.strictEqual(message.createHashDigest, md5);
+      assert.strictEqual(message.oneShotHashDigest, md5);
+      assert.deepStrictEqual(message.hashes, hashes);
+    }));
+    worker.postMessage('fips-off');
+  }));
+  worker.postMessage('fips-on');
+}));
