+assert.deepStrictEqual(getCipherInfo(algorithm), info);
+assert.strictEqual(getCipherInfo('node-test-unknown-provider-cipher'), undefined);
+assert.strictEqual(getCipherInfo('node-test-unknown-provider-cipher'), undefined);
