+static int
+check(int condition, const char *message)
+{
+    if (condition) {
+        return 0;
+    }
+    PyErr_SetString(PyExc_AssertionError, message);
+    return -1;
+}
+
+static int
+check_system_error(int failed, const char *message)
+{
+    if (!failed || !PyErr_ExceptionMatches(PyExc_SystemError)) {
+        PyErr_SetString(PyExc_AssertionError, message);
+        return -1;
+    }
+    PyErr_Clear();
+    return 0;
+}
