+static int
+same_cursor(const _PyTok_Cursor *left, const _PyTok_Cursor *right)
+{
+    return left->source == right->source &&
+        left->pos == right->pos &&
+        left->line_start == right->line_start &&
+        left->line_end == right->line_end &&
+        left->lineno == right->lineno;
+}
