+        memcpy(bytes, source->bytes, source->len);
+    }
+#else
+    bytes = PyMem_Realloc(source->bytes, cap);
+#endif
+    if (bytes == NULL) {
+        PyErr_NoMemory();
+        return -1;
+    }
+#ifdef Py_DEBUG
+    if (source->bytes != NULL) {
+        memset(source->bytes, 0xDD, source->cap);
