+      serverSession.destroy();
+      socket.destroy();
+      source.destroy();
+    }));
+  });
+
+  stream.respond();
+  source.pipe(stream);
+}));
+
+// Manually send a single request with all required preamble:
+socket.push(Buffer.concat([
+  preface,
+  settings(),
+  connectionWindowUpdate(),
+  request(),
+]));

