+static Py_ssize_t
+raw_line_length(const char *data, Py_ssize_t len)
+{
+    for (Py_ssize_t i = 0; i < len; i++) {
+        if (data[i] == '\n') {
+            return i + 1;
+        }
+        if (data[i] == '\r') {
+            return i + 1 < len && data[i + 1] == '\n' ? i + 2 : i + 1;
+        }
+    }
+    return len;
+}
