+        cap *= 2;
+    }
+    char *resized = PyMem_Realloc(*buffer, cap);
+    if (resized == NULL) {
+        PyErr_NoMemory();
+        return -1;
+    }
+    *buffer = resized;
+    *capacity = cap;
+    return 0;
