+        if (result == _PYTOK_READ_EOF) {
+            tok->done = E_EOF;
+        }
+        else if (result == _PYTOK_READ_STOPPED) {
+            tok->done = E_INTERACT_STOP;
+        }
+        else if (result == _PYTOK_READ_INTERRUPT) {
+            tok->done = E_INTR;
+        }
