+    struct tok_state *tok = tokenizer_new_with_reader(kind);
+    if (tok == NULL) {
+        return NULL;
+    }
+    if (encoding != NULL && _PyTok_SetEncoding(tok, encoding) < 0) {
+        _PyTokenizer_Free(tok);
+        return NULL;
+    }
+    tok->fp = fp;
+    tok->prompt = ps1;
