+  const OSSL_PARAM* settable = context.getSettableParams();
+  const OSSL_PARAM* descriptor =
+      settable == nullptr ? nullptr : OSSL_PARAM_locate_const(settable, name);
+  return descriptor != nullptr && descriptor->data_type == type;
