+    '-e', `const m = require('node:module'); if (!m.builtinModules.includes('${builtin}')) process.exit(1); require('${builtin}');`,
+  ], { status: 0 });
+}
+
+const schemeOnlyBuiltins = ['node:test', 'node:sea'];
+if (common.hasSQLite) {
