+    }
+
+    let pending = 0;
+    process.on('exit', () => assert.strictEqual(pending, 0));
+    for (const withFileTypes of [false, true]) {
+      const options = { recursive: true, withFileTypes };
+      check(fs.readdirSync(ALLOWED, options), withFileTypes);
